from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Connect aligned occurrences of each non-background marker; color the
    # intervening background cells with 3 while preserving the markers.
    for r in range(h):
        by_color = {}
        for c, v in enumerate(grid[r]):
            if v != bg:
                by_color.setdefault(v, []).append(c)
        for cols in by_color.values():
            if len(cols) >= 2:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    for c in range(w):
        by_color = {}
        for r in range(h):
            v = grid[r][c]
            if v != bg:
                by_color.setdefault(v, []).append(r)
        for rows in by_color.values():
            if len(rows) >= 2:
                for r in range(min(rows), max(rows) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    return out
